import assert from'node:assert/strict';import test from'node:test';import{PlatformError}from'../../src/foundation/index.js';import{DEBUGGING_DIAGNOSTICS_TRACING_SUPPORT_BUNDLES_ERROR_CODE,DebuggingDiagnosticsTracingSupportBundlesDescriptor as D,DebuggingDiagnosticsTracingSupportBundlesProfile as P}from'../../src/cli-ide-local-tooling/index.js';const K=['logFields','traceFields','healthCheckFields','explainPlanFields','redactionFields','supportBundleFields','correlationRemediationFields','controls','failureRecovery','observabilityFields','assuranceEvidence','invariants'];const complete=d=>{const x={};for(const k of K)x[k]=d[k]();return new P({profileName:'XeniosAI diagnostics',...x})};test('ARCH-035-07 exposes log trace health explain redaction bundle and correlation remediation metadata',()=>{const d=new D();assert.ok(d.logFields().includes('secret-token-and-classified-field-redaction-before-write'));assert.ok(d.traceFields().includes('correlation-and-trace-context-propagation-to-services'));assert.ok(d.healthCheckFields().includes('aggregate-readiness-verdict-for-a-given-command'));assert.ok(d.explainPlanFields().includes('no-side-effect-preview-execution-mode'));assert.ok(d.redactionFields().includes('fail-closed-when-redaction-cannot-be-guaranteed'));assert.ok(d.supportBundleFields().includes('explicit-user-confirmation-of-contents-before-creation-and-sharing'));assert.ok(d.correlationRemediationFields().includes('remediation-suggestions-are-proposed-never-auto-applied'));assert.ok(d.invariants().includes('a-support-bundle-is-never-created-or-shared-without-explicit-user-confirmation-of-its-contents'))});test('ARCH-035-07 validates redaction consent transport correlation privacy and machine boundaries',()=>{const d=new D();assert.equal(d.validateProfile(complete(d)).isValid,true);const r=d.validateProfile({diagnosticsGrantAuthority:true,secretsInLogs:true,secretsInSupportBundle:true,bundleSharedWithoutConsent:true,customerDataInDiagnostics:true,aiSilentlyRemediates:true,correlationIdMissing:true,staleDiagnosticsUnlabeled:true,hiddenPartialFailure:true});assert.equal(r.isValid,false);assert.match(r.errors.join('\n'),/creating or sharing a support bundle without explicit user consent/);assert.match(r.errors.join('\n'),/source code request\/response payloads or customer data in diagnostics/);assert.match(r.errors.join('\n'),/AI assistance silently applying remediation/);assert.match(r.errors.join('\n'),/invocations without a surfaced correlation identifier/);const m=d.validateProfile({profileName:'x',logsRedacted:false,bundlesScrubbed:false,contextExplained:false});assert.match(m.errors.join('\n'),/requires secret and classified field redaction before logs are written/);assert.match(m.errors.join('\n'),/requires an explain plan of resolved context and planned actions/)});test('ARCH-035-07 detects incomplete metadata and preserves immutability',()=>{class I extends D{redactionFields(){return[]}}assert.throws(()=>new I().assertArchitecture(),e=>e instanceof PlatformError&&e.code===DEBUGGING_DIAGNOSTICS_TRACING_SUPPORT_BUNDLES_ERROR_CODE);assert.throws(()=>complete(new D()).traceFields.push('x'),TypeError);assert.equal(new D().assertArchitecture().isValid,true)});
